CREATE OR REPLACE FUNCTION get_alerts (
  p_branch  IN VARCHAR2 DEFAULT NULL,
  p_min_amt IN NUMBER   DEFAULT NULL,
  p_from_dt IN DATE     DEFAULT NULL
) RETURN SYS_REFCURSOR
IS
  l_sql VARCHAR2(4000) :=
    'SELECT alert_id, cust_id, branch_code, alert_amt, alert_dt'
    || ' FROM aml_alert WHERE status = ''OPEN''';
  l_rc  SYS_REFCURSOR;
BEGIN
  IF p_branch IS NOT NULL THEN
    l_sql := l_sql || ' AND branch_code = :b';
  ELSE
    l_sql := l_sql || ' AND (1 = 1 OR :b IS NULL)';
  END IF;

  IF p_min_amt IS NOT NULL THEN
    l_sql := l_sql || ' AND alert_amt >= :a';
  ELSE
    l_sql := l_sql || ' AND (1 = 1 OR :a IS NULL)';
  END IF;

  IF p_from_dt IS NOT NULL THEN
    l_sql := l_sql || ' AND alert_dt >= :d';
  ELSE
    l_sql := l_sql || ' AND (1 = 1 OR :d IS NULL)';
  END IF;

  l_sql := l_sql || ' ORDER BY alert_amt DESC';

  OPEN l_rc FOR l_sql USING p_branch, p_min_amt, p_from_dt;
  RETURN l_rc;
END get_alerts;
/
